-- ----------------------------
-- Table structure for RSK_SPECIFIC_ASSET_TYPE
-- ----------------------------
CREATE TABLE "RSK_SPECIFIC_ASSET_TYPE" (
"SPECIFIC_ID" VARCHAR2(32 BYTE) NOT NULL ,
"BRANCH" NUMBER(10) NOT NULL ,
"TYPE_1" VARCHAR2(32 BYTE) NULL ,
"TYPE_2" VARCHAR2(32 BYTE) NULL ,
"TYPE_3" VARCHAR2(32 BYTE) NULL ,
"TYPE_4" VARCHAR2(32 BYTE) NULL ,
"FINPROD_ID" VARCHAR2(50 BYTE) NULL ,
"IS_BADASSET" VARCHAR2(32 BYTE) NULL ,
"IS_UNLISTEDEQUITY" VARCHAR2(32 BYTE) NULL ,
"IS_REGULATION" VARCHAR2(32 BYTE) NULL ,
"CREATE_USER" VARCHAR2(20 BYTE) NOT NULL ,
"CREATE_DEPT" VARCHAR2(32 BYTE) NULL ,
"CREATE_TIME" TIMESTAMP(6)  NOT NULL ,
"UPDATE_USER" VARCHAR2(20 BYTE) NOT NULL ,
"UPDATE_TIME" TIMESTAMP(6)  NOT NULL ,
"IS_CREDIT_ASSET" VARCHAR2(32 BYTE) NULL ,
"IS_FLOW_LIMITED" VARCHAR2(50 BYTE) NULL 
);


COMMENT ON TABLE "RSK_SPECIFIC_ASSET_TYPE" IS '特定资产类型设置';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."SPECIFIC_ID" IS '特殊资产类型ID';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."BRANCH" IS '分支序号';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."TYPE_1" IS '一级分类';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."TYPE_2" IS '二级分类';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."TYPE_3" IS '三级分类';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."TYPE_4" IS '业务类型';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."FINPROD_ID" IS '资产代码';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."IS_BADASSET" IS '是否不良资产/收受益权';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."IS_UNLISTEDEQUITY" IS '是否未上市股权/收受益权';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."IS_REGULATION" IS '是否国务院银行业监督管理机构另有规定';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."CREATE_USER" IS '创建人';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."CREATE_DEPT" IS '创建部门';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."CREATE_TIME" IS '创建时间';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."UPDATE_USER" IS '更新人';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."UPDATE_TIME" IS '更新时间';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."IS_CREDIT_ASSET" IS '是否信贷资产及其收受益权';
COMMENT ON COLUMN "RSK_SPECIFIC_ASSET_TYPE"."IS_FLOW_LIMITED" IS '是否流动性受限';


ALTER TABLE "RSK_SPECIFIC_ASSET_TYPE" ADD CHECK ("SPECIFIC_ID" IS NOT NULL);
ALTER TABLE "RSK_SPECIFIC_ASSET_TYPE" ADD CHECK ("BRANCH" IS NOT NULL);
ALTER TABLE "RSK_SPECIFIC_ASSET_TYPE" ADD CHECK ("CREATE_USER" IS NOT NULL);
ALTER TABLE "RSK_SPECIFIC_ASSET_TYPE" ADD CHECK ("CREATE_TIME" IS NOT NULL);
ALTER TABLE "RSK_SPECIFIC_ASSET_TYPE" ADD CHECK ("UPDATE_USER" IS NOT NULL);
ALTER TABLE "RSK_SPECIFIC_ASSET_TYPE" ADD CHECK ("UPDATE_TIME" IS NOT NULL);


ALTER TABLE "RSK_SPECIFIC_ASSET_TYPE" ADD PRIMARY KEY ("SPECIFIC_ID");




